    <h1>Pendulum Simulation</h1>
    <input id="initial-angle" type="number" value="45" />
    <button id="start-button">Release Pendulum</button>
    <canvas id="pendulum-canvas" width="400" height="400"></canvas>
    <script>
        const canvas = document.getElementById('pendulum-canvas');
        const ctx = canvas.getContext('2d');
        ctx.translate(200, 200); // translate the origin to the center of the canvas

        let radius = 50;
        let initialAngle;
        let angle = 0;
        let velocity = 0;
        let g = 0.0981; // acceleration due to gravity (m/s²), the value is approximate for the Earth's surface

        document.getElementById('start-button').addEventListener('click', () => {
            initialAngle = document.getElementById('initial-angle').value * Math.PI / 180; // convert degrees to radians
            simulate();
        });

        function simulate() {
            angle += velocity;
            velocity -= g * (Math.sin(angle) ** 2);

            ctx.clearRect(-200, -200, 400, 400);
            ctx.beginPath();
            ctx.fillStyle = 'black';
            ctx.arc(Math.cos(angle) * radius, Math.sin(angle) * radius, radius, 0, 2 * Math.PI);
            ctx.fill();

            if (Math.abs(velocity) < 0.01 && Math.abs(angle) < 0.01) {
                // the pendulum has stopped, stop the simulation
                return;
            }

            requestAnimationFrame(simulate);
        }
    </script>
</body>
</html>
